CREATE OR REPLACE FUNCTION nexus.partition_copy_access(p_parent regclass, p_child regclass, p_force boolean) RETURNS void LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp AS $fn$ DECLARE v_ns text; v_child text; r record; BEGIN SELECT n.nspname::text, c.relname::text INTO v_ns, v_child FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace WHERE c.oid = p_child;
EXECUTE pg_catalog.format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', v_ns, v_child); IF p_force THEN EXECUTE pg_catalog.format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY', v_ns, v_child); ELSE EXECUTE pg_catalog.format('ALTER TABLE %I.%I NO FORCE ROW LEVEL SECURITY', v_ns, v_child); END IF;
-- Policies: drop what the parent does not have, then (re)create each of the parent's. FOR r IN SELECT p.polname FROM pg_catalog.pg_policy p WHERE p.polrelid = p_child AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_policy q WHERE q.polrelid = p_parent AND q.polname = p.polname) LOOP EXECUTE pg_catalog.format('DROP POLICY %I ON %I.%I', r.polname, v_ns, v_child); END LOOP; FOR r IN SELECT p.polname, p.polcmd, p.polpermissive, (SELECT pg_catalog.string_agg(pg_catalog.quote_ident(ro.rolname), ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro WHERE ro.oid = ANY (p.polroles)) AS roles, pg_catalog.pg_get_expr(p.polqual, p.polrelid) AS qual, pg_catalog.pg_get_expr(p.polwithcheck, p.polrelid) AS chk FROM pg_catalog.pg_policy p WHERE p.polrelid = p_parent ORDER BY p.polname LOOP EXECUTE pg_catalog.format('DROP POLICY IF EXISTS %I ON %I.%I', r.polname, v_ns, v_child); EXECUTE pg_catalog.format('CREATE POLICY %I ON %I.%I AS %s FOR %s TO %s%s%s', r.polname, v_ns, v_child, CASE WHEN r.polpermissive THEN 'PERMISSIVE' ELSE 'RESTRICTIVE' END, CASE r.polcmd WHEN 'r' THEN 'SELECT' WHEN 'a' THEN 'INSERT' WHEN 'w' THEN 'UPDATE' WHEN 'd' THEN 'DELETE' ELSE 'ALL' END, COALESCE(r.roles, 'PUBLIC'), CASE WHEN r.qual IS NULL THEN '' ELSE ' USING (' || r.qual || ')' END, CASE WHEN r.chk IS NULL THEN '' ELSE ' WITH CHECK (' || r.chk || ')' END); END LOOP;
-- Grants: revoke what the child has beyond its owner, then grant what the parent has beyond its owner. FOR r IN SELECT DISTINCT a.grantee FROM pg_catalog.pg_class c CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) a WHERE c.oid = p_child AND a.grantee <> c.relowner LOOP EXECUTE pg_catalog.format('REVOKE ALL ON %I.%I FROM %s', v_ns, v_child, CASE WHEN r.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(r.grantee)) END); END LOOP; FOR r IN SELECT a.grantee, a.privilege_type, a.is_grantable FROM pg_catalog.pg_class c CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) a WHERE c.oid = p_parent AND a.grantee <> c.relowner AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles ro WHERE ro.oid = a.grantee AND ro.rolbypassrls) ORDER BY a.grantee, a.privilege_type LOOP EXECUTE pg_catalog.format('GRANT %s ON %I.%I TO %s%s', r.privilege_type, v_ns, v_child, CASE WHEN r.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(r.grantee)) END, CASE WHEN r.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END); END LOOP; END $fn$;

